      featureId,
      workspaceId,
      handle,
      taskRepoUrl,
      taskRepoBranch,
      taskBaseBranch,
      taskRepoBaseBranch,
      executorWorkdir,
      mgmtRepoUrl,
      resultPath,
      budgetTokens,
      implementationModel,
      sshPrivateKey,
      githubToken,
      callbackUrl,
      nonce,
