/**
 * DockerSpawner — relocated from the orchestrator's DockerRunAdapter.
 *
 * Responsibilities:
 *   - Accepts a DispatchJob + credentials and spawns an executor container.
 *   - Reconciles EXECUTOR_WORKDIR vs. /workspace bind-mount: the host
 *     workspacesDir/exec-<handle> is mounted at /workspace inside the
 *     container; EXECUTOR_WORKDIR is always set to /workspace so the
 *     executor writes land on the bind-mounted volume, not the ephemeral layer.
 *   - Sets LOG_SINK=none so the executor logs to stdout rather than the
 *     management repo (standalone path).
 *   - Checks whether a container labelled platform.handle=<handle> already
 *     exists (post-spawn backstop to avoid duplicate containers).
 *
 * It does NOT hold a supervision map or broker connection — those concerns
 * belong to the dispatch stream consumer.
 */

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { DispatchJob } from "@workflow/runtime-abi";

const execFileAsync = promisify(execFile);

export interface DockerSpawnerOpts {
  dockerBin?: string;
  executorImage?: string;
  platformBinDir?: string;
  workspacesDir: string;
  dockerNetwork?: string;
  runnerEntrypoint?: string;
}

export interface SpawnResult {
  containerId: string;
}

export class DockerSpawner {
  private readonly dockerBin: string;
  private readonly executorImage: string;
  private readonly platformBinDir: string;
  private readonly workspacesDir: string;
  private readonly dockerNetwork: string;
  private readonly runnerEntrypoint: string;

  constructor(opts: DockerSpawnerOpts) {
    this.dockerBin = opts.dockerBin ?? "docker";
    this.executorImage = opts.executorImage ?? "executor:current";
    this.platformBinDir = opts.platformBinDir ?? "/workflow/runtime/runner-wrapper";
    this.workspacesDir = opts.workspacesDir;
    this.dockerNetwork = opts.dockerNetwork ?? "agents-net";
    this.runnerEntrypoint = opts.runnerEntrypoint ?? "/platform/runner.js";
  }

  /**
   * Check whether a container with the given platform.handle label already
   * exists (running or exited). Returns the container ID if found, or null.
   *
   * This is the post-spawn backstop — it is not a substitute for the
   * pre-spawn spawn lock (SET NX PX), which closes the TOCTOU window.
   */
  async findExistingContainer(handle: string): Promise<string | null> {
    try {
      const { stdout } = await execFileAsync(this.dockerBin, [
        "ps", "-a",
        "--filter", `label=platform.handle=${handle}`,
        "--format", "{{.ID}}",
      ]);
      const id = stdout.trim();
      return id.length > 0 ? id : null;
    } catch {
      return null;
    }
  }

  /**
   * Spawn a container for the given dispatch job.
   *
   * The host workspacesDir/exec-<handle> is mounted at /workspace.
   * EXECUTOR_WORKDIR inside the container is always /workspace — this
   * reconciles the EXECUTOR_WORKDIR (host path) vs. /workspace bind-mount
   * mismatch: the executor derives its impl/mgmt subdirs from /workspace,
   * so writes land on the bind-mounted volume rather than the ephemeral layer.
   *
   * LOG_SINK=none disables the git flush on the standalone path.
   */
  async spawn(
    job: DispatchJob,
    githubToken: string,
    sshPrivateKey: string,
  ): Promise<SpawnResult> {
    const containerName = `exec-${job.handle}`;
    const containerWorkdir = "/workspace";

    const envArgs: string[] = [
      "-e", `TASK_ID=${job.task_id}`,
      "-e", `FEATURE_ID=${job.feature_id}`,
      "-e", `WORKSPACE_ID=${job.workspace_id}`,
      "-e", `TASK_REPO_URL=${job.task_repo_url}`,
      "-e", `TASK_REPO_BRANCH=${job.task_repo_branch}`,
      "-e", `TASK_BASE_BRANCH=${job.task_base_branch}`,
      "-e", `TASK_REPO_BASE_BRANCH=${job.task_repo_base_branch}`,
      // Reconciled: always /workspace inside the container.
      "-e", `EXECUTOR_WORKDIR=${containerWorkdir}`,
      "-e", `MGMT_REPO_URL=${job.mgmt_repo_url}`,
      "-e", `RESULT_PATH=${containerWorkdir}/result.json`,
      "-e", `CALLBACK_URL=${job.callback_url}`,
      "-e", `HANDLE=${job.handle}`,
      "-e", `NONCE=${job.nonce}`,
      "-e", `GITHUB_TOKEN=${githubToken}`,
      "-e", `LOG_SINK=none`,
    ];

    if (sshPrivateKey) {
      envArgs.push("-e", `SSH_PRIVATE_KEY=${sshPrivateKey}`);
    }
    if (job.budget_tokens !== undefined) {
      envArgs.push("-e", `BUDGET_TOKENS=${job.budget_tokens}`);
    }
    if (job.implementation_model) {
      envArgs.push("-e", `IMPLEMENTATION_MODEL=${job.implementation_model}`);
    }

    const volumeArgs = [
      "-v", `${this.platformBinDir}:/platform:ro`,
      "-v", `${this.workspacesDir}/exec-${job.handle}:/workspace:rw`,
    ];

    const dockerArgs = [
      "run", "-d",
      "--name", containerName,
      "--network", this.dockerNetwork,
      "--entrypoint", this.runnerEntrypoint,
      "--restart=no",
      "--label", `platform.handle=${job.handle}`,
      ...envArgs,
      ...volumeArgs,
      this.executorImage,
    ];

    const { stdout } = await execFileAsync(this.dockerBin, dockerArgs);
    return { containerId: stdout.trim() };
  }
}

