  emit({ type: "dispatcher_starting", consumer_id: config.consumerId });

  const redis = createClient({ url: config.redisUrl }) as RedisClientType;

  redis.on("error", (err) => {
    emit({ type: "redis_error", error: String(err) });
  });

  await redis.connect();
  emit({ type: "redis_connected", url: config.redisUrl });

  const credential = new EnvCredentialAdapter();
  const spawner = new DockerSpawner({
    dockerBin: config.dockerBin,
    executorImage: config.executorImage,
    platformBinDir: config.platformBinDir,
    workspacesDir: config.workspacesDir,
    dockerNetwork: config.dockerNetwork,
  });

  const consumer = new DispatchStreamConsumer({
    redis,
    spawner,
    credential,
    brokerUrl: config.brokerUrl,
    consumerId: config.consumerId,
    maxConcurrent: config.maxConcurrent,
    maxDeliveries: config.maxDeliveries,
    spawnLockTtlMs: config.spawnLockTtlMs,
    pollBlockMs: config.pollBlockMs,
    xautoclaimMinIdleMs: config.xautoclaimMinIdleMs,
    batchSize: config.batchSize,
  });

  let stopping = false;

  async function shutdown(signal: string): Promise<void> {
    if (stopping) return;
    stopping = true;
    emit({ type: "dispatcher_stopping", signal });
    consumer.stop();
    await redis.quit();
    emit({ type: "dispatcher_stopped" });
  }

  process.on("SIGTERM", () => { shutdown("SIGTERM").catch(console.error); });
  process.on("SIGINT",  () => { shutdown("SIGINT").catch(console.error); });

  emit({ type: "dispatcher_started", consumer_id: config.consumerId });
  await consumer.run();
}

main().catch((err) => {
  console.error(JSON.stringify({ at: new Date().toISOString(), type: "dispatcher_fatal", error: String(err) }));
  process.exit(1);
});

