/**
 * Unit tests for DispatchStreamConsumer.
 *
 * All Redis and spawner interactions are faked — no real Redis or Docker required.
 *
 * Scenarios:
 *   1. Happy path: job consumed, container spawned, XACK'd.
 *   2. Spawn lock: exactly one winner spawns when two dispatchers race.
 *   3. DLQ routing: job moved to DLQ + synthetic /callback after maxDeliveries.
 *   4. Cap enforcement: spawn skipped when registry-size >= maxConcurrent.
 *   5. XAUTOCLAIM redelivery: stuck entries are reclaimed and processed.
 *   6. Duplicate container: label-backstop check prevents second spawn.
 *   7. Malformed entry: ACK'd and discarded without crashing.
 */

import { describe, it, expect, beforeEach, vi } from "vitest";
import { randomUUID } from "node:crypto";
import { DispatchStreamConsumer, type ConsumerOpts } from "../src/consumer.js";
import type { DispatchJob } from "@workflow/runtime-abi";
import { DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, DISPATCH_DLQ_KEY } from "@workflow/runtime-abi";
import type { DockerSpawner } from "../src/spawner.js";
import type { CredentialAdapter } from "../src/credential.js";

// ── Fake implementations ──────────────────────────────────────────────────────

function makeJob(overrides?: Partial<DispatchJob>): DispatchJob {
  return {
    handle: randomUUID(),
    nonce: randomUUID(),
    kind: "impl",
    task_id: "T4",
    feature_id: "standalone-executor-hardening",
    workspace_id: "ws-test",
    task_repo_url: "git@github.com:org/repo.git",
    task_repo_branch: "feature/test-T4",
    task_base_branch: "feature/standalone-executor-hardening",
    task_repo_base_branch: "main",
    mgmt_repo_url: "git@github.com:org/workspace.git",
    executor_workdir: "/workspace",
    callback_url: "http://broker:7000/callback",
    enqueued_at: new Date().toISOString(),
    ...overrides,
  };
}

function makeEntry(job: DispatchJob, id?: string): { id: string; message: Record<string, string> } {
  return { id: id ?? `${Date.now()}-0`, message: { job: JSON.stringify(job) } };
}

interface FakeRedis {
  // Collected calls for assertion
  xAddCalls: Array<{ key: string; id: string; fields: Record<string, string> }>;
  xAckCalls: Array<{ key: string; group: string; id: string }>;
  xPendingRangeResults: Map<string, { deliveryCount: number }[]>;
  setCalls: Array<{ key: string; value: string; opts: { NX?: boolean; PX?: number } }>;
  setResults: Map<string, string | null>;
  getCalls: string[];
  getResults: Map<string, string | null>;
  delCalls: string[];

  // Behaviour overrides
  xAdd: ReturnType<typeof vi.fn>;
  xAck: ReturnType<typeof vi.fn>;
  xPendingRange: ReturnType<typeof vi.fn>;
  set: ReturnType<typeof vi.fn>;
  get: ReturnType<typeof vi.fn>;
  del: ReturnType<typeof vi.fn>;
  xGroupCreate: ReturnType<typeof vi.fn>;
  xReadGroup: ReturnType<typeof vi.fn>;
  xAutoClaim: ReturnType<typeof vi.fn>;
}

function makeFakeRedis(opts?: {
  pendingByEntryId?: Map<string, number>;
  setResultFn?: (key: string) => string | null;
}): FakeRedis {
  const xAddCalls: FakeRedis["xAddCalls"] = [];
  const xAckCalls: FakeRedis["xAckCalls"] = [];
  const setCalls: FakeRedis["setCalls"] = [];
  const getCalls: string[] = [];
  const delCalls: string[] = [];

  const r: FakeRedis = {
    xAddCalls,
    xAckCalls,
    xPendingRangeResults: new Map(),
    setCalls,
    setResults: new Map(),
    getCalls,
    getResults: new Map(),
    delCalls,

    xAdd: vi.fn(async (key: string, id: string, fields: Record<string, string>) => {
      xAddCalls.push({ key, id, fields });
      return "1-0";
    }),
    xAck: vi.fn(async (key: string, group: string, id: string) => {
      xAckCalls.push({ key, group, id });
      return 1;
    }),
    xPendingRange: vi.fn(async (key: string, group: string, start: string, end: string, count: number) => {
      const entryId = start; // our call uses same start=end=entryId
      const deliveryCount = opts?.pendingByEntryId?.get(entryId) ?? 1;
      return [{ id: entryId, deliveryCount, consumer: "test", idle: 100 }];
    }),
    set: vi.fn(async (key: string, value: string, setOpts: { NX?: boolean; PX?: number }) => {
      setCalls.push({ key, value, opts: setOpts });
      if (opts?.setResultFn) return opts.setResultFn(key);
      // Default: always grant the lock (return "OK")
      return "OK";
    }),
    get: vi.fn(async (key: string) => {
      getCalls.push(key);
      return null;
    }),
    del: vi.fn(async (key: string) => {
      delCalls.push(key);
      return 1;
    }),
    xGroupCreate: vi.fn(async () => "OK"),
    xReadGroup: vi.fn(async () => []),
    xAutoClaim: vi.fn(async () => ({ nextId: "0-0", messages: [] })),
  };
  return r;
}

function makeFakeSpawner(opts?: {
  existingHandle?: string;
  spawnError?: Error;
}): DockerSpawner & { spawnCalls: DispatchJob[] } {
  const spawnCalls: DispatchJob[] = [];
  return {
    spawnCalls,
    findExistingContainer: vi.fn(async (handle: string) => {
      return opts?.existingHandle === handle ? "fake-container-id" : null;
    }),
    spawn: vi.fn(async (job: DispatchJob) => {
      if (opts?.spawnError) throw opts.spawnError;
      spawnCalls.push(job);
      return { containerId: `container-${job.handle}` };
    }),
  } as unknown as DockerSpawner & { spawnCalls: DispatchJob[] };
}

function makeFakeCredential(): CredentialAdapter {
  return {
    getGitHubToken: vi.fn(async () => "fake-token"),
    getSshPrivateKey: vi.fn(async () => "fake-key"),
  };
}

const BASE_OPTS = {
  brokerUrl: "http://broker:7000",
  consumerId: "test-dispatcher",
  maxConcurrent: 5,
  maxDeliveries: 3,
  spawnLockTtlMs: 300_000,
  pollBlockMs: 100,
  xautoclaimMinIdleMs: 30_000,
  batchSize: 10,
};

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("DispatchStreamConsumer", () => {

  describe("_processEntry — happy path", () => {
    it("spawns container, then XACKs on success", async () => {
      const redis = makeFakeRedis();
      const spawner = makeFakeSpawner();
      const credential = makeFakeCredential();

      const consumer = new DispatchStreamConsumer({
        redis: redis as any,
        spawner,
        credential,
        ...BASE_OPTS,
      });

      // Stub _getRegistrySize to return 0 (cap not exceeded).
      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(0);

      const job = makeJob();
      const entry = makeEntry(job, "100-0");

      await (consumer as any)._processEntry(entry);

      expect(spawner.spawnCalls).toHaveLength(1);
      expect(spawner.spawnCalls[0].handle).toBe(job.handle);
      expect(redis.xAckCalls).toHaveLength(1);
      expect(redis.xAckCalls[0].id).toBe("100-0");
    });
  });

  describe("spawn lock — exactly one winner", () => {
    it("only one dispatcher spawns when two race on the same entry", async () => {
      // First dispatcher gets lock, second doesn't.
      let firstCall = true;
      const setResultFn = (_key: string): string | null => {
        if (firstCall) { firstCall = false; return "OK"; }
        return null; // second call loses
      };

      const redis1 = makeFakeRedis({ setResultFn: () => "OK" });
      const redis2 = makeFakeRedis({ setResultFn: () => null });

      const spawner1 = makeFakeSpawner();
      const spawner2 = makeFakeSpawner();

      const c1 = new DispatchStreamConsumer({ redis: redis1 as any, spawner: spawner1, credential: makeFakeCredential(), ...BASE_OPTS });
      const c2 = new DispatchStreamConsumer({ redis: redis2 as any, spawner: spawner2, credential: makeFakeCredential(), ...BASE_OPTS });

      vi.spyOn(c1, "_getRegistrySize" as any).mockResolvedValue(0);
      vi.spyOn(c2, "_getRegistrySize" as any).mockResolvedValue(0);

      const job = makeJob();
      const entry = makeEntry(job, "200-0");

      await Promise.all([
        (c1 as any)._processEntry(entry),
        (c2 as any)._processEntry(entry),
      ]);

      // Exactly one spawner should have been called.
      const totalSpawns = spawner1.spawnCalls.length + spawner2.spawnCalls.length;
      expect(totalSpawns).toBe(1);

      // Loser should have XACK'd to drop from its PEL.
      // c2 lost the lock → it XACK'd without spawning.
      expect(redis2.xAckCalls).toHaveLength(1);
    });
  });

  describe("DLQ routing", () => {
    it("moves job to DLQ and posts synthetic /callback after maxDeliveries", async () => {
      const job = makeJob({ callback_url: "http://broker:7000/callback" });
      const entryId = "300-0";
      const pendingByEntryId = new Map([[entryId, 4]]); // > maxDeliveries=3

      const redis = makeFakeRedis({ pendingByEntryId });
      const spawner = makeFakeSpawner();

      const postedCallbacks: string[] = [];
      const consumer = new DispatchStreamConsumer({
        redis: redis as any,
        spawner,
        credential: makeFakeCredential(),
        ...BASE_OPTS,
      });

      // Stub httpPost to capture synthetic callback.
      let dlqCallbackPosted = false;
      vi.spyOn(consumer as any, "_moveToDlq").mockImplementation(async (id: string, j: DispatchJob) => {
        dlqCallbackPosted = true;
        // Simulate XADD to DLQ + XACK.
        await redis.xAdd(DISPATCH_DLQ_KEY, "*", { job: JSON.stringify(j) });
        await redis.xAck(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, id);
      });

      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(0);

      const entry = makeEntry(job, entryId);
      await (consumer as any)._processEntry(entry);

      expect(dlqCallbackPosted).toBe(true);
      // Should have written to DLQ stream.
      const dlqWrites = redis.xAddCalls.filter((c) => c.key === DISPATCH_DLQ_KEY);
      expect(dlqWrites).toHaveLength(1);
      // Should have XACK'd.
      expect(redis.xAckCalls.some((c) => c.id === entryId)).toBe(true);
      // Spawner should NOT have been called.
      expect(spawner.spawnCalls).toHaveLength(0);
    });
  });

  describe("cap enforcement", () => {
    it("skips spawning when registry-size >= maxConcurrent", async () => {
      const redis = makeFakeRedis();
      const spawner = makeFakeSpawner();
      const consumer = new DispatchStreamConsumer({
        redis: redis as any,
        spawner,
        credential: makeFakeCredential(),
        ...BASE_OPTS,
        maxConcurrent: 3,
      });

      // Registry already at cap.
      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(3);

      const job = makeJob();
      const entry = makeEntry(job, "400-0");
      await (consumer as any)._processEntry(entry);

      // No spawn, no XACK (left in PEL for later).
      expect(spawner.spawnCalls).toHaveLength(0);
      expect(redis.xAckCalls).toHaveLength(0);
    });
  });

  describe("XAUTOCLAIM redelivery", () => {
    it("processes entries returned by XAUTOCLAIM", async () => {
      const job = makeJob();
      const reclaimedEntry = makeEntry(job, "500-0");

      const redis = makeFakeRedis();
      // Return reclaimed entry on first xAutoClaim call.
      (redis.xAutoClaim as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
        nextId: "0-0",
        messages: [reclaimedEntry],
      });

      const spawner = makeFakeSpawner();
      const consumer = new DispatchStreamConsumer({
        redis: redis as any,
        spawner,
        credential: makeFakeCredential(),
        ...BASE_OPTS,
      });

      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(0);
      consumer.stop(); // stop after one iteration

      // Run one iteration manually via _xautoclaim.
      const reclaimed = await (consumer as any)._xautoclaim();
      expect(reclaimed).toHaveLength(1);
      expect(reclaimed[0].id).toBe("500-0");

      await (consumer as any)._processEntry(reclaimed[0]);
      expect(spawner.spawnCalls).toHaveLength(1);
    });
  });

  describe("duplicate container backstop", () => {
    it("skips spawn when container with platform.handle label exists", async () => {
      const job = makeJob();
      const redis = makeFakeRedis();
      const spawner = makeFakeSpawner({ existingHandle: job.handle });
      const consumer = new DispatchStreamConsumer({
        redis: redis as any,
        spawner,
        credential: makeFakeCredential(),
        ...BASE_OPTS,
      });

      vi.spyOn(consumer, "_getRegistrySize" as any).mockResolvedValue(0);

      const entry = makeEntry(job, "600-0");
      await (consumer as any)._processEntry(entry);

      // Spawn not called; XACK'd to remove from PEL.
      expect(spawner.spawnCalls).toHaveLength(0);
      expect(redis.xAckCalls).toHaveLength(1);
      expect(redis.xAckCalls[0].id).toBe("600-0");
    });
  });

  describe("malformed entry", () => {
    it("ACKs and discards a malformed stream entry without crashing", async () => {
      const redis = makeFakeRedis();
      const spawner = makeFakeSpawner();
      const consumer = new DispatchStreamConsumer({
        redis: redis as any,
        spawner,
        credential: makeFakeCredential(),
        ...BASE_OPTS,
      });

      const badEntry = { id: "700-0", message: { job: "{ not valid json" } };
      await (consumer as any)._processEntry(badEntry);

      expect(spawner.spawnCalls).toHaveLength(0);
      expect(redis.xAckCalls).toHaveLength(1);
      expect(redis.xAckCalls[0].id).toBe("700-0");
    });
  });

  describe("_acquireSpawnLock", () => {
    it("returns true when SET NX succeeds", async () => {
      const redis = makeFakeRedis();
      const consumer = new DispatchStreamConsumer({ redis: redis as any, spawner: makeFakeSpawner(), credential: makeFakeCredential(), ...BASE_OPTS });
      const acquired = await (consumer as any)._acquireSpawnLock("dispatch:lock:handle-1", "owner-1");
      expect(acquired).toBe(true);
      expect(redis.setCalls).toHaveLength(1);
      expect(redis.setCalls[0].opts.NX).toBe(true);
      expect(redis.setCalls[0].opts.PX).toBe(BASE_OPTS.spawnLockTtlMs);
    });

    it("returns false when SET NX returns null (lock held by another)", async () => {
      const redis = makeFakeRedis({ setResultFn: () => null });
      const consumer = new DispatchStreamConsumer({ redis: redis as any, spawner: makeFakeSpawner(), credential: makeFakeCredential(), ...BASE_OPTS });
      const acquired = await (consumer as any)._acquireSpawnLock("dispatch:lock:handle-2", "owner-2");
      expect(acquired).toBe(false);
    });
  });
});

